sub compress {
    my ($input_text) = @_;

    # Build operation list
    my @operations = ();
    my $pos = 0;
    my $data_len = length($input_text);

    while ($pos < $data_len) {
        my ($offset, $length) = find_matches($input_text, $pos, 31, 7);

        if (defined $offset) {
            # Back-reference
            push @operations, ['ref', $offset - 1, $length - 1];
            $pos += $length;
        } else {
            # Literal
            my $char_val = ord(substr($input_text, $pos, 1));
            if ($char_val > 127) {
                $char_val = $char_val - 256;  # Convert to signed
            }
            push @operations, ['lit', $char_val];
            $pos += 1;
        }
    }

    # Encode
    my $encoder = ArithmeticEncoder->new();

    # Encode number of operations
    $encoder->put_integer(scalar @operations, 9, 0);

    # Encode each operation
    foreach my $op (@operations) {
