 1;\\n50|}\\n51|\\n52|sub put_integer {\\n53|    my ($self, $value, $tmp, $ctx) = @_;\\n54|    \\n55|    my $subtract_it = 1 << $tmp;\\n56|    my $encoded_value = $value + $subtract_it;\\n57|    \\n58|    # Find the bit length\\n59|    my $bit_len = 0;\\n60|    my $temp = $encoded_value;\\n61|    while ($temp > 0) {\\n62|        $bit_len++;\\n63|        $temp >>= 1;\\n64|    }\\n65|    $bit_len -= 1;\\n66|    \\n67|    $ctx *= 99;\\n68|    # Encode unary: bit_len zeros followed by a one\\n69|    for (my $i = 0; $i < $bit_len; $i++) {\\n70|        $self->put_bit(0, $tmp + 1 + $i + $ctx);\\n71|    }\\n72|    $self->put_bit(1, $tmp + 1 + $bit_len + $ctx);\\n73|    \\n74|    # Encode the bits from high to low (excluding the leading 1)\\n75|    for (my $i = $bit_len - 1; $i >= 0; $i--) {\\n76|        my $bit_val = ($encoded_value >> $i) & 1;\\n77|        $self->put_bit($bit_val, $ctx);\\n78|    }\\n79|}\\n80|\\n81|sub flush {\\n82|    my $self = shift;\\n83|    \\n84|    # Output enough to disambiguate\\n85|    for (my $i = 0; $i < 10; $i++) {\\n86|        push @{$self->{output}}, int($self->{low} / $self->{radix}) + 1;\\n87|        $self->{low} = ($self->{low} % $self->{radix}) * $self->{radix};\\n88|    }\\n89|    \\n90|    return pack('C*', @{$self->{output}});\\n91|}\\n92|\\n93|package main;\\n94|\\n95|sub find_matches {\\n96|    my ($data, $pos, $max_offset, $max_len) = @_;\\n97|    $max_offset //= 31;\\n98|    $max_len //= 7;\\n99|    \\n100|    return (undef, 0) if $pos == 0;\\n101|    \\n102|    my $best_len = 0;\\n103|    my $best_offset = 0;\\n104|    \\n105|    # Search backward for matches\\n106|    my $search_start = $pos - $max_offset;\\n107|    $search_start = 0 if $search_start < 0;\\n108|    \\n109|    for (my $offset = 1; $offset <= $pos - $search_start && $offset <= $max_offset; $offset++) {\\n110|        my $match_pos = $pos - $offset;\\n111|        last if $match_pos < 0;\\n112|        \\n113|        # Check how long the match is\\n114|        my $match_len = 0;\\n115|        while ($match_len < $max_len && \\n116|               $pos + $match_len < length($data) &&\\n117|               substr($data, $match_pos + $match_len, 1) eq substr($data, $pos + $match_len, 1)) {\\n118|            $match_len++;\\n119|        }\\n120|        \\n121|        if ($match_len > $best_len) {\\n122|            $best_len = $match_len;\\n123|            $best_offset = $offset;\\n124|        }\\n125|    }\\n126|    \\n127|    # Only return match if it's worth encoding (length >= 2)\\n128|    if ($best_len >= 2) {\\n129|        return ($best_offset, $best_len);\\n130|    }\\n131|    return (undef, 0);\\n132|}\\n133|\\n134|sub compress {\\n135|    my ($input_text) = @_;\\n136|    \\n137|    # Build operation list\\n138|    my @operations = ();\\n139|    my $pos = 0;\\n140|    my $data_len = length($input_text);\\n141|    \\n142|    while ($pos < $data_len) {\\n143|        my ($offset, $length) = find_matches($input_text, $pos, 31, 7);\\n144|        \\n145|        if (defined $offset) {\\n146|            # Back-reference\\n147|            push @operations, ['ref', $offset - 1, $length - 1];\\n148|            $pos += $length;\\n149|        } else {\\n150|            # Literal\\n151|            my $char_val = ord(substr($input_text, $pos, 1));\\n152|            if ($char_val > 127) {\\n153|                $char_val = $char_val - 256;  # Convert to signed\\n154|            }\\n155|            push @operations, ['lit', $char_val];\\n156|            $pos += 1;\\n157|        }\\n158|    }\\n159|    \\n160|    # Encode\\n161|    my $encoder = ArithmeticEncoder->new();\\n162|    \\n163|    # Encode number of operations\\n164|    $encoder->put_integer(scalar @operations, 9, 0);\\n165|    \\n166|    # Encode each operation\\n167|    foreach my $op (@operations) {\\n168|        if ($op->[0] eq 'ref') {\\n169|            # Back-reference\\n170|            $encoder->put_bit(1, 1);\\n171|            $encoder->put_integer($op->[1], 5, 2);  # OFF1=5, ctx=2\\n172|            $encoder->put_integer($op->[2], 2, 3);  # OFF2=2, ctx=3\\n173|        } else {\\n174|            # Literal\\n175|            $encoder->put_bit(0, 1);\\n176|            my $char_val = $op->[1];\\n177|            if ($char_val < 0) {\\n178|                $encoder->put_bit(1, 8);  # sign bit\\n179|                $encoder->put_integer(-$char_val, 4, 9);\\n180|            } else {\\n181|                $encoder->put_bit(0, 8);  # sign bit\\n182|                $encoder->put_integer($char_val, 4, 9);\\n183|            }\\n184|        }\\n185|    }\\n186|    \\n187|    return $encoder->flush();\\n188|}\\n189|\\n190|# Main\\n191|open(my $fh, '<', '/app/data.txt') or die \\\"Cannot open data.txt: $!\\\";\\n192|my $input_text = do { local $/; <$fh> };\\n193|close($fh);\\n194|\\n195|my $compressed = compress($input_text);\\n196|\\n197|open(my $out, '>', '/app/data.comp') or die \\\"Cannot write data.comp: $!\\\";\\n198|binmode($out);\\n199|print $out $compressed;\\n200|close($out);\", \"next_prompt\": \"\\n\"}], \"current_runtime_instructions\": \"\\n\\n\\n\\n[SYSTEM] 必须在回复文本中包含<summary>！\\n\\n\", \"response_content\": \"I need to examine the encoder.pl literal encoding logic to verify it matches the decoder's expectations for sign bit (context 8) and magnitude (context 9 with LITSIZE=4).\", \"exit_reason\": {}}"}


