#include <stdlib.h>
#include <string.h>

#define RADIX 255
#define OFF1 5
#define OFF2 2
#define LITSIZE 4

int cc[1000000] = {0};
long low = 0;
long range = 1;

unsigned char output[100000];
int output_len = 0;

void normalize() {
    while (range < RADIX) {
        output[output_len++] = (low / RADIX) + 1;
        low = (low % RADIX) * RADIX;
        range *= RADIX;
    }
}

void put_bit(int bit, int ctx) {
    normalize();
    int *counts = cc + ctx * 2;
    long split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);

    if (bit) {
        low += split;
        range -= split;
        counts[1]++;
    } else {
        range = split;
        counts[0]++;
    }
}

void put_integer(int value, int tmp, int ctx) {
    int subtract_it = 1 << tmp;
    value += subtract_it;

    ctx *= 99;
    int bit_len = 0;
    int v = value;
    while (v > 1) {
        v >>= 1;
        bit_len++;
    }

    for (int i = 0; i < bit_len; i++) {
        put_bit(0, tmp + 1 + ctx);
        tmp++;
    }
    put_bit(1, tmp + 1 + ctx);

    for (int i = bit_len - 1; i >= 0; i--) {
        put_bit((value >> i) & 1, ctx);
    }
}

void flush() {
    for (int i = 0; i < 10; i++) {
        output[output_len++] = (low / RADIX) + 1;
        low = (low % RADIX) * RADIX;
    }
}

typedef struct {
    int type;
    int value;
    int len;
} Operation;

Operation ops[100000];
int op_count = 0;

int find_match(unsigned char *data, int pos, int len, int *best_offset, int *best_len) {
    *best_len = 0;
    *best_offset = 0;

    int max_offset = 31;
    int max_len = 7;

    int start = pos - max_offset;
    if (start < 0) start = 0;

    for (int i = start; i < pos; i++) {
        int match_len = 0;
        while (match_len < max_len && pos + match_len < len && 
               data[i + match_len] == data[pos + match_len]) {
            match_len++;
        }

        if (match_len >= 2 && match_len > *best_len) {
            *best_len = match_len;
            *best_offset = pos - i;
        }
    }

    return *best_len >= 2;
}

void compress(unsigned char *data, int len) {
    op_count = 0;
    int pos = 0;

    while (pos < len) {
        int offset, match_len;
        if (find_match(data, pos, len, &offset, &match_len)) {
            ops[op_count].type = 1;
            ops[op_count].value = offset - 1;
            ops[op_count].len = match_len - 1;
            op_count++;
            pos += match_len;
        } else {
            ops[op_count].type = 0;
            ops[op_count].value = (int)(signed char)data[pos];
            op_count++;
            pos++;
        }
    }
}

void encode_operations() {
    put_integer(op_count, 9, 0);

    for (int i = 0; i < op_count; i++) {
        if (ops[i].type == 1) {
            put_bit(1, 1);
            put_integer(ops[i].value, OFF1, 2);
            put_integer(ops[i].len, OFF2, 3);
        } else {
            put_bit(0, 1);
            int val = ops[i].value;
            if (val < 0) {
                put_bit(1, 8);
                put_integer(-val, LITSIZE, 9);
            } else {
                put_bit(0, 8);
                put_integer(val, LITSIZE, 9);
            }
        }
    }
}

int main() {
    unsigned char data[100000];
    int len = fread(data, 1, sizeof(data), stdin);

    compress(data, len);
    encode_operations();
    flush();

    fwrite(output, 1, output_len, stdout);

    return 0;
}
