typedef struct {
    int type;
    int value;
    int len;
} Operation;

Operation ops[100000];
int op_count = 0;

int find_match(unsigned char *data, int pos, int len, int *best_offset, int *best_len) {
    *best_len = 0;
    *best_offset = 0;

    int max_offset = 31;
    int max_len = 7;

    int start = pos - max_offset;
    if (start < 0) start = 0;

    for (int i = start; i < pos; i++) {
        int match_len = 0;
        while (match_len < max_len && pos + match_len < len && 
