unsigned char output[100000];
int output_len = 0;

void normalize() {
    while (range < RADIX) {
        output[output_len++] = (low / RADIX) + 1;
        low = (low % RADIX) * RADIX;
        range *= RADIX;
    }
}

void put_bit(int bit, int ctx) {
    normalize();
    int *counts = cc + ctx * 2;
    long split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);

    if (bit) {
        low += split;
        range -= split;
        counts[1]++;
    } else {
        range = split;
        counts[0]++;
    }
}

void put_integer(int value, int tmp, int ctx) {
    int subtract_it = 1 << tmp;
    value += subtract_it;

    ctx *= 99;
    int bit_len = 0;
    int v = value;
    while (v > 1) {
        v >>= 1;
        bit_len++;
    }

    for (int i = 0; i < bit_len; i++) {
        put_bit(0, tmp + 1 + ctx);
        tmp++;
    }
    put_bit(1, tmp + 1 + ctx);

    for (int i = bit_len - 1; i >= 0; i--) {
        put_bit((value >> i) & 1, ctx);
    }
}

void flush() {
    for (int i = 0; i < 10; i++) {
        output[output_len++] = (low / RADIX) + 1;
        low = (low % RADIX) * RADIX;
    }
