#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define RADIX 255
#define OFF1 5
#define OFF2 2
#define LITSIZE 4

int cc[1000000] = {0};
long low = 0;
long range = 1;

unsigned char output[100000];
int output_len = 0;

void normalize() {
    while (range < RADIX) {
        output[output_len++] = (low / RADIX) + 1;
        low = (low % RADIX) * RADIX;
        range *= RADIX;
    }
}

void put_bit(int bit, int ctx) {
    normalize();
    int *counts = cc + ctx * 2;
    long split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);

    if (bit) {
        low += split;
        range -= split;
        counts[1]++;
    } else {
        range = split;
        counts[0]++;
    }
}

void put_integer(int value, int tmp, int ctx) {
    int subtract_it = 1 << tmp;
    value += subtract_it;

